package com.emssystem.emsleaveservice.pto.entity; import com.emssystem.emsleaveservice.pto.enums.PtoLedgerEntryType; import com.emssystem.emsleaveservice.shared.entity.AuditableEntity; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="pto_ledger_entries",indexes=@Index(name="idx_pto_ledger_employee_type_time",columnList="employee_id,pto_type_id,occurred_at")) public class PtoLedgerEntry extends AuditableEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(name="employee_id",nullable=false) private Long employeeId;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="pto_type_id",nullable=false) private PtoType ptoType;@Column(name="hours_delta",nullable=false,precision=10,scale=2) private BigDecimal hoursDelta;@Enumerated(EnumType.STRING) @Column(name="entry_type",nullable=false,length=20) private PtoLedgerEntryType entryType;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="source_request_id") private PtoRequest sourceRequest;@Column(name="occurred_at",nullable=false) private Instant occurredAt;protected PtoLedgerEntry(){}public PtoLedgerEntry(Long employeeId,PtoType type,BigDecimal delta,PtoLedgerEntryType entryType,PtoRequest source,Instant occurredAt){this.employeeId=employeeId;this.ptoType=type;this.hoursDelta=delta;this.entryType=entryType;this.sourceRequest=source;this.occurredAt=occurredAt;}public Long getId(){return id;}public Long getEmployeeId(){return employeeId;}public PtoType getPtoType(){return ptoType;}public BigDecimal getHoursDelta(){return hoursDelta;}public PtoLedgerEntryType getEntryType(){return entryType;}public PtoRequest getSourceRequest(){return sourceRequest;}public Instant getOccurredAt(){return occurredAt;}}
